@torch.jit.script
def _candidate_norm_gru_scan(projected: torch.Tensor, hidden: torch.Tensor,
                             weight_hh: torch.Tensor, bias_hh: torch.Tensor,
                             norm_weight: torch.Tensor, norm_bias: torch.Tensor):
    states = torch.jit.annotate(list[torch.Tensor], [])
    for step in projected.unbind(1):
        recurrent = torch.nn.functional.linear(hidden, weight_hh, bias_hh)
        input_reset, input_update, input_candidate = step.chunk(3, dim=-1)
        hidden_reset, hidden_update, hidden_candidate = recurrent.chunk(3, dim=-1)
        reset = torch.sigmoid(input_reset + hidden_reset)
        update = torch.sigmoid(input_update + hidden_update)
        candidate_pre = input_candidate + reset * hidden_candidate
        candidate = torch.tanh(torch.nn.functional.layer_norm(
            candidate_pre, [hidden.size(1)], norm_weight, norm_bias, 1e-5
        ))
        hidden = (1.0 - update) * candidate + update * hidden
        states.append(hidden)
    return torch.stack(states, dim=1), hidden


class CandidateNormGRU(nn.GRU):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.candidate_norms = nn.ModuleList([
            nn.LayerNorm(self.hidden_size) for _ in range(self.num_layers)
        ])

    def forward(self, input, hx=None):
        layer_input = input if self.batch_first else input.transpose(0, 1)
        final_states = []
        for layer, norm in enumerate(self.candidate_norms):
            hidden = (layer_input.new_zeros(layer_input.size(0), self.hidden_size)
                      if hx is None else hx[layer])
            projected = torch.nn.functional.linear(
                layer_input, getattr(self, f'weight_ih_l{layer}'),
                getattr(self, f'bias_ih_l{layer}')
            )
            layer_output, hidden = _candidate_norm_gru_scan(
                projected, hidden, getattr(self, f'weight_hh_l{layer}'),
                getattr(self, f'bias_hh_l{layer}'), norm.weight, norm.bias
            )
            final_states.append(hidden)
            if layer < self.num_layers - 1:
                layer_input = torch.nn.functional.dropout(
                    layer_output, p=self.dropout, training=self.training
                )
            else:
                layer_input = layer_output
        output = layer_input if self.batch_first else layer_input.transpose(0, 1)
        return output, torch.stack(final_states, dim=0)


